"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisCtaContent } from "./components/cta-sections/content";
import View9 from "./components/cta-sections/variants/10-split";
const views={"split":View9};
export type { ArtemisCtaContent, ArtemisCtaImage, ArtemisCtaLink, ArtemisCtaQuestion, ArtemisCtaStat } from "./components/cta-sections/content";
export interface ArtemisCtaSectionsProps{className?:string;variant?:"split"; /** The words on the CTA section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisCtaContent>; }
export function ArtemisCtaSections({className,variant="split",content}:ArtemisCtaSectionsProps){const View=views[variant];return <ArtemisScope className={className}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisCtaLink {
  label: string;
  href: string;
}

/** A picture, and the words that describe it. */
export interface ArtemisCtaImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** A figure with a short label under it. */
export interface ArtemisCtaStat {
  /** The figure as text, such as "120" or "4.9". Its digits roll into place. */
  value: string;
  /** Shown right after the figure, such as "K+" or "/5". */
  suffix?: string;
  /** What the figure counts. */
  label: string;
}

/** A question and its answer. */
export interface ArtemisCtaQuestion {
  question: string;
  answer: string;
  /** A short id, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
}

/** The words on an Artemis CTA section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisCtaContent {
  /** The short line above the heading. sunflower, product-window, proof-orbit, shade-panel, glow and terminal. */
  badge?: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's second part. glow shows it on a line of its own in a muted tone; faq, terminal and split start a new line for it; the other layouts run it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The main button. All layouts. */
  cta: ArtemisCtaLink;
  /** A second button. floating-gallery, portrait-frame, glow, terminal and split. */
  secondaryCta?: ArtemisCtaLink;
  /** A quiet text link under the buttons. split. */
  link?: ArtemisCtaLink;
  /** A short line near the buttons. sunflower, portrait-frame, proof-orbit and glow. */
  note?: string;
  /** The picture beside the words. portrait-frame, which also blurs it behind the panel, and glow. */
  image?: ArtemisCtaImage;
  /** Photos floating at the sides. floating-gallery: up to six, in pairs from the top, left then right; under 768px wide only the first two show. */
  images?: ArtemisCtaImage[];
  /** Faces in a row above the words. proof-orbit: up to five, from the left; the third is the largest. */
  avatars?: ArtemisCtaImage[];
  /** What the row of faces shows, read by screen readers. proof-orbit. Left out, it keeps the layout's own only when `avatars` is left out too. */
  avatarsLabel?: string;
  /** Figures under the buttons. floating-gallery; four look best. */
  stats?: ArtemisCtaStat[];
  /** Short facts along the foot of the panel. glow. */
  highlights?: string[];
  /** An install command with a copy button. terminal types it out; split shows it on its button. */
  command?: string;
  /** The lines the terminal prints after `command`. terminal. Left out, it keeps the layout's own lines only when `command` is left out too. */
  commandOutput?: string[];
  /** Questions with answers that open one at a time; the first starts open. faq. */
  questions?: ArtemisCtaQuestion[];
}

"use client";
// @zeus-internal
import { motion, type Transition, useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { useArtemisReduceAfterHydration } from "../../../lib/use-reduce-after-hydration";
import type { ArtemisCtaContent, ArtemisCtaLink } from "../content";
const DEFAULT = {
    headline: "Build the interface",
    headlineAccent: "your product deserves.",
    subhead: "Premium, animated components and full page templates that drop straight into your stack. Own the source, ship the polish.",
    command: "npx zeus-ui add artemis-hero-sections",
    cta: { label: "Browse components", href: "#" },
    secondaryCta: { label: "Star on GitHub", href: "#" },
    link: { label: "Read the docs", href: "#" },
} satisfies ArtemisCtaContent;
const COPIED_MS = 1500;
const WORD_HIDDEN = { opacity: 0, filter: "blur(10px)", y: "40%" };
const WORD_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const WORD_STAGGER = 0.09;
const BLOCK_HIDDEN = { opacity: 0, filter: "blur(6px)", y: 16 };
const BLOCK_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const BLOCK_IN_VIEW = { once: true, margin: "-60px" } as const;
const BLOCK_REDUCED = { opacity: 1, filter: "none", transform: "none" };
const GLOW_STYLE = {
    background: "conic-gradient(from 90deg at 50% 50%, #f59e0b, #fb7185, #22d3ee, #34d399, #f59e0b)",
    inset: "-8px",
    filter: "blur(24px)",
    opacity: "0.7",
};
const GLOW_HUE = { filter: ["blur(24px) hue-rotate(0deg)", "blur(24px) hue-rotate(360deg)"] };
const GLOW_SCALE = { rest: { scale: 1 }, hover: { scale: 1.06 } };
const GLOW_LOOP: Transition = { duration: 4.5, ease: "linear", repeat: Infinity };
function wordTransition(index: number): Transition {
    const delay = index * WORD_STAGGER;
    return {
        opacity: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay },
        filter: { duration: 0.9, ease: ARTEMIS_EASE_OUT, delay },
        y: { type: "spring", stiffness: 140, damping: 26, mass: 1.2, delay },
    };
}
function blockTransition(delay: number): Transition {
    return { duration: 0.6, ease: ARTEMIS_EASE_OUT, delay };
}
function Word({ index, reduce, children }: {
    index: number;
    reduce: boolean;
    children: ReactNode;
}) {
    if (reduce) {
        return (<span className="art:inline-block art:will-change-transform" style={{ opacity: 1, filter: "none", transform: "none" }}>
        {children}
      </span>);
    }
    return (<motion.span className="art:inline-block art:will-change-transform" initial={WORD_HIDDEN} animate={WORD_SHOWN} transition={wordTransition(index)}>
      {children}
    </motion.span>);
}
function Heading({ reduce, lines }: {
    reduce: boolean;
    lines: string[];
}) {
    const rows = lines.map((text) => text.split(/\s+/).filter(Boolean));
    let index = 0;
    return (<h2 className="art:block art:max-w-xl art:text-balance art:font-sans art:text-foreground art:text-4xl art:font-medium">
      {rows.map((line) => (<span key={line.join(" ")} className="art:block">
          {line.map((word, i) => {
                const n = index++;
                return (<Word key={i} index={n} reduce={reduce}>
                {word}
                {i < line.length - 1 ? <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">{"\u00A0"}</span> : null}
              </Word>);
            })}
        </span>))}
    </h2>);
}
function CopyIcon() {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-copy art:size-3.5 art:text-muted-foreground art:transition-colors art:group-hover:text-foreground" aria-hidden="true">
      <rect width="14" height="14" x="8" y="8" rx="2" ry="2"/>
      <path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/>
    </svg>);
}
function CheckIcon() {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-3.5 art:text-success" aria-hidden="true">
      <path d="M20 6 9 17l-5-5"/>
    </svg>);
}
function InstallButton({ press, command }: {
    press: boolean;
    command: string;
}) {
    const [copied, setCopied] = useState(false);
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
    useEffect(() => () => {
        if (timer.current)
            clearTimeout(timer.current);
    }, []);
    const copy = () => {
        if (!navigator.clipboard)
            return;
        navigator.clipboard.writeText(command).then(() => {
            setCopied(true);
            if (timer.current)
                return;
            timer.current = setTimeout(() => {
                timer.current = null;
                setCopied(false);
            }, COPIED_MS);
        }, () => undefined);
    };
    return (<motion.button type="button" className="art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:hover:text-inherit art:group art:inline-flex art:items-center art:gap-3 art:border art:border-border art:bg-background art:py-2.5 art:pr-3 art:pl-4 art:font-mono art:text-foreground art:text-sm art:transition-colors art:hover:border-border/70 art:hover:bg-muted art:rounded-full" aria-label={copied ? "Copied" : "Copy install command"} tabIndex={0} onClick={copy} whileHover={press ? { scale: 1.01 } : undefined} whileTap={press ? { scale: 0.99 } : undefined} transition={ARTEMIS_SPRING_PRESS}>
      <span>
        <span className="art:text-muted-foreground">{"$"}</span>
        {" "}
        {command}
      </span>
      {copied ? <CheckIcon /> : <CopyIcon />}
    </motion.button>);
}
function GlowCta({ press, hue, cta }: {
    press: boolean;
    hue: boolean;
    cta: ArtemisCtaLink;
}) {
    return (<motion.span className="art:relative art:inline-flex art:isolate art:w-full" initial="rest" animate="rest" whileHover="hover">
      <motion.span className="art:absolute art:inset-0" variants={GLOW_SCALE} transition={ARTEMIS_SPRING_PRESS}>
        {hue ? (<motion.span aria-hidden="true" className="art:pointer-events-none art:absolute art:rounded-full art:transform-gpu" style={GLOW_STYLE} initial={{ filter: "blur(24px)" }} animate={GLOW_HUE} transition={GLOW_LOOP}/>) : (<span aria-hidden="true" className="art:pointer-events-none art:absolute art:rounded-full art:transform-gpu" style={GLOW_STYLE}/>)}
      </motion.span>
      <motion.a className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:h-12 art:gap-2 art:rounded-full art:px-6 art:text-base art:relative art:z-10 art:w-full art:bg-primary art:text-primary-foreground art:hover:bg-primary/90" href={cta.href} tabIndex={0} whileHover={press ? { scale: 1.01 } : undefined} whileTap={press ? { scale: 0.99 } : undefined} transition={ARTEMIS_SPRING_PRESS}>
        {cta.label}
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
          <path d="M5 12h14"/>
          <path d="m12 5 7 7-7 7"/>
        </svg>
      </motion.a>
    </motion.span>);
}
function Reveal({ as, reduce, delay, className, children }: {
    as: "p" | "div";
    reduce: boolean;
    delay: number;
    className: string;
    children: ReactNode;
}) {
    if (reduce) {
        const Tag = as;
        return (<Tag className={className} style={BLOCK_REDUCED}>
        {children}
      </Tag>);
    }
    const Tag = as === "p" ? motion.p : motion.div;
    return (<Tag className={className} initial={BLOCK_HIDDEN} whileInView={BLOCK_SHOWN} viewport={BLOCK_IN_VIEW} transition={blockTransition(delay)}>
      {children}
    </Tag>);
}
export default function CtaSectionsSplit({ content }: { content?: Partial<ArtemisCtaContent> } = {}) {
    const words = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? words.headlineAccent : content.headlineAccent;
    const reduce = useArtemisReduceAfterHydration();
    const press = !(useReducedMotion() ?? false);
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-16 art:@min-[640px]/artemis:px-8">
          <div className="art:relative art:mx-auto art:w-full art:max-w-5xl art:overflow-hidden art:rounded-2xl art:border art:border-border art:px-6 art:py-14 art:@min-[640px]/artemis:px-12 art:@min-[640px]/artemis:py-16">
            <div className="art:relative art:grid art:items-center art:gap-10 art:@min-[1024px]/artemis:grid-cols-[1fr_auto] art:@min-[1024px]/artemis:gap-16">
              <div className="art:flex art:flex-col art:items-start art:text-left">
                <Heading reduce={reduce} lines={accent ? [words.headline, accent] : [words.headline]}/>
                <Reveal as="p" reduce={reduce} delay={0.12} className="art:mt-5 art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-7 art:@min-[640px]/artemis:text-base">
                  {words.subhead}
                </Reveal>
                <Reveal as="div" reduce={reduce} delay={0.2} className="art:mt-7">
                  <InstallButton press={press} command={words.command}/>
                </Reveal>
              </div>
              <Reveal as="div" reduce={reduce} delay={0.28} className="art:flex art:w-full art:flex-col art:items-stretch art:gap-3 art:@min-[1024px]/artemis:w-64">
                <GlowCta press={press} hue={!reduce} cta={words.cta}/>
                <motion.a className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:hover:border-border art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:w-full art:border-border art:bg-background art:text-foreground art:hover:bg-muted art:h-9 art:rounded-full" href={words.secondaryCta.href} tabIndex={0} whileHover={press ? { scale: 1.01 } : undefined} whileTap={press ? { scale: 0.99 } : undefined} transition={ARTEMIS_SPRING_PRESS}>
                  {words.secondaryCta.label}
                </motion.a>
                <a href={words.link.href} className="art:group art:mt-1 art:inline-flex art:items-center art:justify-center art:gap-1 art:text-muted-foreground art:text-sm art:transition-colors art:hover:text-foreground">
                  {words.link.label}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-right art:size-3.5 art:transition-transform art:group-hover:translate-x-0.5" aria-hidden="true">
                    <path d="m9 18 6-6-6-6"/>
                  </svg>
                </a>
              </Reveal>
            </div>
          </div>
        </section>
      </div>
    </>);
}
